    url = "http://example.com//foo"
    pr.prepare_url(url, None)
    print(f"URL: {url} -> Prepared URL: {pr.url}")
    assert pr.url == "http://example.com//foo" # Current behavior

if __name__ == "__main__":
    try:
        test_excess_slashes()
        print("Current behavior verified: double slash preserved.")
    except AssertionError as e:
        print(f"Assertion failed: {e}")

